DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q25$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$Hormones are the primary factors that account for the differences in age-related heart disease risks between women and men.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q25 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q25$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$Estrogen and testosterone are the only hormones that promote or inhibit heart disease.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q25 B'; END IF; END $guard$;
