INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The physician need not believe hormones are the *primary* explanation. The conclusion says testosterone and estrogen *tend* to influence heart disease, which allows other factors to be important or even dominant.$batch01$), ($batch01$B$batch01$, $batch01$Nothing here requires these to be the only relevant hormones. Another hormone could also promote or inhibit disease.$batch01$), ($batch01$C$batch01$, $batch01$The speaker compares men and women at different life stages to suggest effects of hormones. The argument does not need young high-testosterone men to have higher risk than postmenopausal women.$batch01$), ($batch01$D$batch01$, $batch01$The observed hormone differences and heart disease patterns are correlations. To conclude that testosterone promotes and estrogen inhibits the disease, the physician assumes those correlations reflect causal influence. A shared cause or another sex-related difference could instead explain the pattern.$batch01$), ($batch01$E$batch01$, $batch01$Hormone levels could vary substantially within age and gender groups while the described average patterns still hold. The causal inference does not depend on identical levels among all people in a group.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT111-S3-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
